import java.util.*;

class Solution {
    public int[] nextGreaterElements(int[] nums) {
        int n = nums.length;
        int[] res = new int[n];
        Arrays.fill(res, -1);
        Deque<Integer> stack = new ArrayDeque<>(); // store indices, decreasing values

        for (int i = 0; i < 2 * n; i++) {
            int idx = i % n;
            int val = nums[idx];
            while (!stack.isEmpty() && nums[stack.peek()] < val) {
                res[stack.pop()] = val;
            }
            if (i < n) {
                stack.push(idx);
            }
        }
        return res;
    }
}

